#include <iostream>
#include <mutex>
#include <thread>
#include <vector>

long sum = 0;
std::mutex m;

void work() {
    std::unique_lock<std::mutex> lk(m);   // 可延迟/手动 unlock，配合条件变量
    for (int k = 0; k < 1000; ++k) ++sum;
    lk.unlock();                           // 提前释放，缩小临界区
}

int main() {
    std::vector<std::thread> ts;
    for (int i = 0; i < 2; ++i) ts.emplace_back(work);
    for (auto& t : ts) t.join();
    std::cout << "sum=" << sum;   // 2*1000=2000，确定性
}
